	L.SetGlobal("cPet_ChangeMind", L.NewFunction(func(L *glua.LState) int {
		petHandle := uint32(L.OptInt(1, 0))
		mind := 50
		if L.Get(2).Type() == glua.LTString {
			switch L.OptString(2, "") {
			case "follow":
				mind = 1
			case "revolution":
				mind = 2
			case "dance":
				mind = 3
			case "attack":
				mind = 4
			case "talk":
				mind = 5
			}
		} else {
			mind = L.OptInt(2, 50)
		}
		br.PetChangeMind(petHandle, mind)
		return 0
	}))
